--- ClientKeyResolver.cs ---
namespace Service;

/// <summary>
/// Resolves the partition key used to bucket rate-limit counters for a request: the caller's
/// API key if supplied via the <c>X-Api-Key</c> header, otherwise the caller's source IP
/// address. This is purely a client-identity signal for rate limiting — it is not an
/// authentication or authorization mechanism, and no key value is validated.
/// </summary>
public static class ClientKeyResolver
{
    private const string ApiKeyHeaderName = "X-Api-Key";

    /// <summary>Computes the partition key for a request.</summary>
    public static string Resolve(HttpContext context)
    {
        if (context.Request.Headers.TryGetValue(ApiKeyHeaderName, out Microsoft.Extensions.Primitives.StringValues values))
        {
            string? apiKey = values.ToString();
            if (!string.IsNullOrEmpty(apiKey))
            {
                return "key:" + apiKey;
            }
        }

        string ip = context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        return "ip:" + ip;
    }

    /// <summary>Truncates a resolved key for safe inclusion in logs.</summary>
    public static string Redact(string clientKey)
    {
        const int visibleChars = 8;
        return clientKey.Length <= visibleChars ? clientKey : clientKey[..visibleChars] + "...";
    }
}

--- CodeGenerator.cs ---
using System.Text;

namespace Service;

/// <summary>Encodes a monotonic identifier as base62, using a fixed alphanumeric alphabet.</summary>
public static class CodeGenerator
{
    private const string Alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    public static string Encode(long id)
    {
        if (id <= 0)
        {
            return Alphabet[0].ToString();
        }

        var builder = new StringBuilder();
        ulong value = (ulong)id;
        while (value > 0)
        {
            builder.Insert(0, Alphabet[(int)(value % 62)]);
            value /= 62;
        }

        return builder.ToString();
    }
}

